-- Generated by Murakumo: load tpch_erp.nation (full), without Murakumo. Run it from the project folder.

-- The files under landing/tpch_erp/nation/ that were not loaded before.
-- Loaded in full: each run fetched the whole table, so only the latest run's files count.
create or replace temp table new_rows as
select cast(n_nationkey as INTEGER) as n_nationkey, cast(n_name as VARCHAR) as n_name, cast(n_regionkey as INTEGER) as n_regionkey, cast(n_comment as VARCHAR) as n_comment, filename
from read_json('landing/tpch_erp/nation/nation_*.jsonl', format = 'newline_delimited', filename = true, columns = {'n_nationkey': 'INTEGER', 'n_name': 'VARCHAR', 'n_regionkey': 'INTEGER', 'n_comment': 'VARCHAR'})
where regexp_extract(filename, '_(\d{8}T\d{12}Z)_', 1) = (select max(regexp_extract(file, '_(\d{8}T\d{12}Z)_', 1)) from glob('landing/tpch_erp/nation/nation_*.jsonl'))
  and parse_filename(filename) not in (select parse_filename(path) from audit.loaded_files where table_name = 'nation');
-- When the latest run is new, its rows replace the table's.
delete from raw_tpch_erp.nation where exists (select 1 from new_rows);
insert into raw_tpch_erp.nation (n_nationkey, n_name, n_regionkey, n_comment, _ingested_at, _batch_id)
select n_nationkey, n_name, n_regionkey, n_comment, now(), parse_filename(filename) from new_rows;
-- Remember the files, so the next run skips them.
insert into audit.loaded_files (table_name, path, size, sha256, rows_ingested, batch_id, loaded_at)
select 'nation', filename, null, null, count(*), parse_filename(filename), now()
from new_rows group by filename;
drop table new_rows;
